// Need to add logic for remove the related struction when some rules are deleted and no other rules under some structure exist.
// In this example code, we do not handle the deletion of structure when rules are deleted (by rule cleanup job). But we handle the logic to refresh all rule structure when the refresh hash
public static void insertOrUpdateGUPRuleHash(GUPPricingRule _pricingRule)
{
    next insertOrUpdateGUPRuleHash(_pricingRule);
    GUPRuleHash::insertStruct(_pricingRule);
}

public static void insertStruct(GUPPricingRule _pricingRule)
{
    // Only insert price attribute group structure with OR relations
    GUPPricingRuleCondition ruleCondition;
    select firstonly RecId from ruleCondition
        where ruleCondition.RuleId == _pricingRule.RecId
               && ruleCondition.METisOR == NoYes::Yes;

    if (!ruleCondition.RecId)
    {
        return;
    }

    str structString = GUPRuleHash::generateStructString(_pricingRule);

    METGUPPricingAttributeGroupRef groupRef;
    select firstonly RecId from groupRef
        where groupRef.PriceAttributeGroupName == _pricingRule.PriceAttributeGroupName
            && groupRef.StructStr == structString;

    if (groupRef.RecId)
    {
        return;
    }

    ttsbegin;
    groupRef.PriceAttributeGroupName = _pricingRule.PriceAttributeGroupName;;
    groupRef.StructStr = structString;
    groupRef.insert();

    GUPPricingAttributeLink attributeLink;
    METGUPPricingAttributeLinkRelation linkRelation;

    // Save the attribute details (OR or AND) for the structure
    while select RecId from attributeLink
        order by attributeLink.Priority
        where attributeLink.PriceAttributeGroupName == _pricingRule.PriceAttributeGroupName
            && attributeLink.Source != GUPPricingAttributeSource::CustomerPriceGroup
            && attributeLink.Source != GUPPricingAttributeSource::ProductPriceGroup
        outer join METisOR from ruleCondition
        where ruleCondition.RuleId == _pricingRule.RecId
            && ruleCondition.ConditionAttribute == attributeLink.RecId
    {
        linkRelation.clear();
        linkRelation.PriceAttributeGroupName = _pricingRule.PriceAttributeGroupName;;
        linkRelation.AttrGroupRefRecId = groupRef.RecId;
        linkRelation.AttrLinkRecId = attributeLink.RecId;
        linkRelation.isOR = ruleCondition.METisOR;
        linkRelation.insert();
    }

    ttscommit;
}

// Generate the unique string for each unique attribute group struct with OR relation to make sure we didn't insert duplicated structure.
public static str generateStructString(GUPPricingRule _pricingRule)
{
    str structString;
    GUPPricingRuleCondition pricingRuleCondition;
    GUPPricingAttributeLink attributeLink;
    GUPPricingRuleCondition ruleCondition;

    while select RecId from attributeLink
        order by attributeLink.Priority
        where attributeLink.PriceAttributeGroupName == _pricingRule.PriceAttributeGroupName
            && attributeLink.Source != GUPPricingAttributeSource::CustomerPriceGroup
            && attributeLink.Source != GUPPricingAttributeSource::ProductPriceGroup
        outer join METisOR from ruleCondition
        where ruleCondition.RuleId == _pricingRule.RecId
               && ruleCondition.ConditionAttribute == attributeLink.RecId
    {
        structString += int642Str(attributeLink.RecId) + ':' + (ruleCondition.METisOR ? '1':'0') + '|';
    }
    return structString;
}

    public static Set getHashKeySetForPricingRule(GUPPricingRule _pricingRule, GUPRuleHash _ruleHash)
    {
        /*
        Attributes: A1, A2, A3, A4, A5
        Values:     V1, V2, V3, V4, V5
        A1:V1    OR
        A2:V2    OR
        A3:V3    OR
        A4:V4
        A5:V5
=>
        (A1 = V1 OR A2 = V2 OR A3 = V3) AND A4 = V4 AND A5 = V5

        in Next () logic: AND attribute first, it is the same with how we generated hash for normal pricing rule
=>  HASH STRING FOR AND ATTRIBUTES
      [A4:V4/A5:V5]
        */

        Set hashKeySet = next getHashKeySetForPricingRule(_pricingRule, _ruleHash);
        GUPPricingRuleCondition pricingRuleCondition;
        select firstonly RecId from pricingRuleCondition
            where pricingRuleCondition.RuleId == _pricingRule.RecId
               && pricingRuleCondition.METisOR == NoYes::Yes;

        if (!pricingRuleCondition.RecId)
        {
            return hashKeySet;
        }

        str hashKey;
        GUPPricingAttributeLink attributeLink;
        List conditionValueList;
        GUPPricingRuleCondition ruleCondition;
        GUPPricingAttributeGroupName groupName = GUPHashHelper::getAttrGroupNameFromRule(_pricingRule);

        // Then OR attributes
        Set orConditionValueSet = new Set(Types::String);
        while select AttributeName, RecId, Priority, PriceAttributeClassId, AttributeProviderClassId, TypeName from attributeLink
            order by attributeLink.Priority
            where attributeLink.PriceAttributeGroupName == _pricingRule.PriceAttributeGroupName
                && attributeLink.Source != GUPPricingAttributeSource::CustomerPriceGroup
                && attributeLink.Source != GUPPricingAttributeSource::ProductPriceGroup
            join ConditionValue from ruleCondition
            where ruleCondition.RuleId == _pricingRule.RecId
                && ruleCondition.ConditionAttribute == attributeLink.RecId
                && ruleCondition.METisOR == NoYes::Yes
        {
            if (GUPHashHelper::shouldSkipEmptyAttribute(ruleCondition.ConditionValue, _pricingRule.PriceAttributeGroupName))
            {
                continue;
            }

            if (ruleCondition.ConditionValue != '')
            {
                conditionValueList = GUPRuleHash::getConditionValueListForRuleHash(_ruleHash, ruleCondition, attributeLink);

                RecId attrLinkRecId = GUPHashHelper::getRecIdFromAttrLink(attributeLink, groupName);

                ListEnumerator conditionValueEnum = conditionValueList.getEnumerator();
                while (conditionValueEnum.moveNext())
                {
                    orConditionValueSet.add(strLRTrim(strLwr(int642Str(attrLinkRecId) + GUPHashHelper::getColonChar() + strLRTrim(conditionValueEnum.current()))));
                }
            }
            else
            {
                orConditionValueSet.add(GUPHashHelper::getAllValue());
            }
        }

        if (orConditionValueSet.empty())
        {
            return hashKeySet;
        }

        /*
=>  HASH STRING FOR OR ATTRIBUTE
      [A1:V1,
       A2:V3,
       A3:V3]
        */

        // concat the AND attributes and OR attributes
        if (hashKeySet.empty())
        {
            hashKeySet = orConditionValueSet;
        }
        else
        {
            Set newHashKeys = new Set(Types::String);
            SetEnumerator setEnumerator = hashKeySet.getEnumerator();
            while (setEnumerator.moveNext())
            {
                SetEnumerator conditionValueEnum = orConditionValueSet.getEnumerator();
                while (conditionValueEnum.moveNext())
                {
                    newHashKeys.add(setEnumerator.current() + GUPHashHelper::getSlashChar() + conditionValueEnum.current());
                }
            }

            hashKeySet = newHashKeys;
        }
        /*
=>  HASH STRING AT THE END
      [A4:V4/A5:V5/A1:V1,
       A4:V4/A5:V5/A2:V3,
       A4:V4/A5:V5/A3:V3]
      */

        return hashKeySet;
    }
